function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2200)}
function go(screen){state.screen=screen;$('.screen').forEach(x=>x.classList.toggle('active',x.dataset.screen===screen));$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.go===screen));$('.bottom-nav').hidden=false;$('.app-shell .topbar').hidden=false;window.scrollTo({top:0,behavior:'instant'});if(screen==='home')renderHome();if(screen==='explore'){if(!state.mapPlanIds)state.mapPlanIds=[];renderMarkers();}if(screen==='library')renderLibrary();if(screen==='been')renderBeen();if(screen==='profile')renderProfile();if(screen==='search')renderSearchPage($('#search-page-input')?.value||'');if(screen==='surprise')renderSurprise();if(screen==='plan-options')renderPlanOptions();if(screen==='planner-detail')renderPlan();if(screen==='active-plan')renderActivePlan();if(screen==='shared-plan')renderSharedReceipt();if(screen==='log-detail')renderLogDetail()}
function save(id,type){const exists=state.saved.some(x=>x.id===id&&x.type===type);const next=exists?state.saved.filter(x=>!(x.id===id&&x.type===type)):[{id,type,at:Date.now()},...state.saved];if(!write('saved',next))return false;state.saved=next;toast(exists?'Removed from your Library':'Saved to your Library');renderLibrary();renderHome();if(type==='place')$('#sheet-detail-save').textContent=isSaved(id,type)?'Saved':'Save place';return true}
async function shareItem(kind,id){const item=kind==='place'?placeBy(id):planBy(id);if(!item)return;const url=new URL(location.href);url.search='';let message;if(kind==='place'){url.searchParams.set('place',id);message=item.name+' · '+item.area+'\nA place I found on Outsideish.'}else{const payload={version:1,name:item.name,time:item.time,area:item.area,mood:item.mood||'',budget:item.budget||'',intro:item.intro,stops:item.stops.map(s=>({id:s.id,title:s.title,note:s.note||''})),places:item.stops.map(s=>placeBy(s.id)).filter(p=>p&&customPlaces.some(x=>x.id===p.id)).map(p=>({id:p.id,name:p.name,area:p.area,type:p.type,desc:p.desc,address:p.address,hours:p.hours,price:p.price,tone:p.tone,tags:p.tags}))};const encoded=btoa(unescape(encodeURIComponent(JSON.stringify(payload)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');url.searchParams.set('outing',encoded);message=item.name+'\n'+payload.stops.map((s,i)=>(i+1)+'. '+s.title).join('\n')+'\nA little outing from Outsideish.'}try{if(navigator.share){await navigator.share({title:item.name,text:message,url:url.toString()})}else if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(url.toString());toast('Share link copied.')}else{const box=document.createElement('textarea');box.value=url.toString();document.body.append(box);box.select();const ok=document.execCommand('copy');box.remove();toast(ok?'Share link copied.':'Sharing is not available here.')}}catch(error){if(error.name!=='AbortError')toast('Could not share this just now.')}}
function visit(id){if(state.visited.some(x=>x.id===id))return true;const next=[{id,at:Date.now(),note:''},...state.visited];if(!write('visited',next))return false;state.visited=next;renderBeen();return true}
