function renderHome(){const name=state.name?', '+escapeText(state.name):'';$('#greeting').innerHTML='Hello'+name+'. <em>Where shall we go?</em>';$('#home-places').innerHTML=places.slice(0,4).map(card).join('');$('#home-plans').innerHTML=[...customPlans,...plans].slice(0,3).map(p=>'<button class="list-row" data-plan="'+p.id+'"><span class="list-art">'+art('lilac')+'</span><span><strong>'+p.name+'</strong><small>'+p.time+' · '+p.area+'</small></span>'+ico('chev')+'</button>').join('');$('#home-collections').innerHTML=[{key:'culture',title:'Art, stories & things to look closer at',note:'Galleries, music history and creative corners',tone:'lilac'},{key:'slow',title:'A slower side of the city',note:'Books, music and unhurried afternoons',tone:'yellow'},{key:'outside',title:'A little more outside',note:'Green spaces, water and room to roam',tone:'sage'}].map(c=>'<button class="collection-row" data-collection="'+c.key+'"><span class="collection-art">'+art(c.tone,c.key==='culture'?'culture':c.key)+'</span><span><strong>'+c.title+'</strong><small>'+c.note+'</small></span>'+ico('chev')+'</button>').join('');$('#home-avatar').innerHTML=state.avatar?'<img src="'+state.avatar+'" alt="">':''}
function renderMarkers(){const coords=[[20,27],[39,39],[55,22],[70,55],[47,70],[80,76],[32,51],[63,88]];const q=(state.mapQuery||'').toLowerCase();const shown=[...places,...customPlaces].filter(p=>(state.mapFilter==='all'||p.tags.includes(state.mapFilter))&&(!q||(p.name+' '+p.area+' '+p.type+' '+p.desc).toLowerCase().includes(q)));$('#map-markers').innerHTML=shown.map(p=>{const i=Math.max(0,places.indexOf(p));const pos=coords[i]||[50,50];return '<button class="map-marker '+(state.mapPlanIds?.includes(p.id)?'plan-stop':'')+'" data-map-place="'+p.id+'" style="left:'+pos[0]+'%;top:'+pos[1]+'%" aria-label="'+p.name+'"><span></span></button>'}).join('');$('#map-world').style.transform='translate(calc(-50% + '+state.mapX+'px),calc(-50% + '+state.mapY+'px)) scale('+state.mapZoom+')';const list=$('#map-list-items');if(list)list.innerHTML=shown.map(p=>'<button class="map-list-item" data-map-place="'+p.id+'"><span class="list-art">'+illustrationFor(p)+'</span><span><strong>'+p.name+'</strong><small>'+p.area+' · '+p.type+'</small></span></button>').join('')||'<p class="muted-note">No matching places. Try another search or filter.</p>'}
