function openPlace(id){const p=placeBy(id);if(!p)return;state.currentPlace=id;$('#sheet-detail-art').innerHTML=illustrationFor(p);$('#sheet-detail-name').textContent=p.name;$('#sheet-detail-meta').textContent=p.area+' · '+p.type;$('#sheet-detail-description').textContent=p.desc;$('#sheet-detail-price').textContent='Estimated spend: '+p.price+'. Confirm current prices before visiting.';$('#sheet-detail-time').textContent='Estimated time: not available for this place yet';$('#sheet-detail-address').textContent=p.area+' · '+p.address;$('#sheet-detail-hours').textContent=p.hours;$('#sheet-detail-save').textContent=isSaved(id,'place')?'Saved':'Save place';$('#sheet-detail-map').hidden=state.screen==='explore';modal('place-modal')}
