function openPlan(id){let p=planBy(id)||state.planCandidates?.find(x=>x.id===id);if(!p)return;if(!customPlans.some(x=>x.id===id)){customPlans.unshift(p);if(!write('customPlans',customPlans))return}const prefs=state.planPreferences||p.preferences||{};if(plans.some(x=>x.id===id)){p={...p,id:'tailored-'+Date.now(),preferences:{...prefs},mood:moodLabel(prefs.mood||state.mood),budget:({any:'Flexible',light:'Keep it light',mid:'A little room',open:'No set budget'}[prefs.budget]||'Flexible')};customPlans.unshift(p);if(!write('customPlans',customPlans))return;id=p.id}state.currentPlan=id;state.sharedMode=false;state.currentPlanPreferences=p.preferences||prefs;state.planStops=p.stops.map(x=>({...x}));state.done=[];state.previousScreen=state.screen;$('.screen[data-screen="planner-detail"] .back-link').dataset.go=state.previousScreen;go('planner-detail')}
