function renderPlan(){const p=planBy(state.currentPlan);if(!p)return;$('#plan-title').textContent=p.name;$('#plan-meta').textContent=[p.mood||state.mood||'A day out',p.time||'Flexible time',p.area||'Lagos'].filter(Boolean).join(' · ');$('#plan-intro').textContent=p.intro||'A little outing, made around the places you want to explore.';$('#plan-progress').textContent=state.planStops.length+' stops · Saved on this device';$('#plan-stops').innerHTML=state.planStops.map((s,i)=>'<div class="receipt-line"><span class="receipt-index">'+String(i+1).padStart(2,'0')+'</span><div><strong>'+escapeText(s.title)+'</strong><small>'+escapeText(s.note||'A stop on your outing')+'</small></div><span class="receipt-cost">Estimate unavailable</span><div class="stop-actions"><button data-swap="'+i+'" aria-label="Swap '+escapeText(s.title)+'">↔</button><button data-remove="'+s.id+'" aria-label="Remove '+escapeText(s.title)+'">'+ico('close')+'</button></div></div>').join('')||'<p class="muted-note">No stops yet. Add one to start shaping your day.</p>';$('#receipt-total-time').textContent=(p.time||'Not specified')+' available · estimated duration not verified';$('#receipt-total-cost').textContent='Estimate unavailable';$('#receipt-total-budget').textContent=p.budget||({any:'Flexible',light:'Keep it light',mid:'A little room',open:'No set budget'}[state.currentPlanPreferences?.budget]||'Flexible')}
function escapeText(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function runSearch(q){const v=q.trim().toLowerCase();if(!v){toast('Try a place, neighbourhood or experience.');return}if(state.screen==='explore'){state.mapQuery=v;renderMarkers();const matches=places.filter(p=>(p.name+' '+p.area+' '+p.type+' '+p.desc).toLowerCase().includes(v));if(!matches.length)toast('No matches on the map. Try another search.');else if(matches.length===1)mapPlace(matches[0].id);return}const matches=places.filter(p=>(p.name+' '+p.area+' '+p.type+' '+p.desc).toLowerCase().includes(v));const panel=$('#search-results');$('#search-results-title').textContent=matches.length?('Found '+matches.length+' '+(matches.length===1?'place':'places')):'No places found';$('#search-results-list').innerHTML=matches.length?matches.map(p=>'<button class="list-row" data-place="'+p.id+'"><span class="list-art">'+illustrationFor(p)+'</span><span><strong>'+p.name+'</strong><small>'+p.area+' · '+p.type+'</small></span>'+ico('chev')+'</button>').join(''):'<div class="empty"><h2>Nothing by that name just yet.</h2><p>Try a neighbourhood, a type of place or a different mood.</p><button class="primary" data-go="explore">Explore the map</button></div>';panel.hidden=false;panel.scrollIntoView({behavior:'smooth',block:'start'})}
function modal(id){const el=$('#'+id);if(!el)return;el.dataset.returnFocus=document.activeElement?.id||'';el.hidden=false;el.querySelector('input:not([type="hidden"]),select,textarea,button')?.focus({preventScroll:true})}function closeModal(id){const el=$('#'+id);if(!el)return;const target=el.dataset.returnFocus;el.hidden=true;if(target&&$('#'+target))$('#'+target).focus({preventScroll:true})}
function startPlan(mood=''){state.mood=mood||'all';$$('[data-mood]').forEach(b=>b.classList.toggle('active',b.dataset.mood===state.mood));modal('planner-modal')}
function renderSearchPage(q=''){const input=$('#search-page-input');if(input&&input.value!==q)input.value=q;const term=q.trim().toLowerCase();const matches=[...places,...customPlaces].filter(p=>(p.name+' '+p.area+' '+p.type+' '+p.desc+' '+p.tags.join(' ')).toLowerCase().includes(term));const host=$('#search-page-results');if(!term){host.innerHTML='<p class="muted-note">Try a place, neighbourhood, interest or experience.</p>';return}host.innerHTML=matches.length?matches.map(p=>'<button class="list-row" data-place="'+p.id+'"><span class="list-art">'+illustrationFor(p)+'</span><span><strong>'+p.name+'</strong><small>'+p.area+' · '+p.type+'</small></span>'+ico('chev')+'</button>').join(''):'<div class="empty"><h2>No match this time.</h2><p>Try a broader search, or wander the illustrated map instead.</p><button class="primary" data-go="explore">Explore the map</button></div>'}
